package com.bank.cleanup;

import org.springframework.stereotype.Service;
import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

@Service
public class StringCleanupService {

    public List<String> cleanArray(String[] input) {
        return Arrays.stream(input)
            .filter(Objects::nonNull)                  // remove nulls
            .filter(Predicate.not(String::isBlank))    // remove empty + whitespace-only
            .map(String::trim)                          // trim remaining strings
            .toList();
    }
}
