package com.bank.cleanup;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.function.Predicate;
import static org.assertj.core.api.Assertions.*;

class StringCleanupTest {

    @Test void removeNullsAndBlanks() {
        String[] arr = {"Rajesh", null, "", "Priya", "  ", null, "Amit", ""};
        List<String> clean = Arrays.stream(arr)
            .filter(Objects::nonNull)
            .filter(Predicate.not(String::isBlank))
            .map(String::trim)
            .toList();
        assertThat(clean).containsExactly("Rajesh", "Priya", "Amit");
    }

    @Test void allNullsAndBlanks() {
        String[] arr = {null, "", "  ", null};
        List<String> clean = Arrays.stream(arr)
            .filter(Objects::nonNull)
            .filter(Predicate.not(String::isBlank))
            .toList();
        assertThat(clean).isEmpty();
    }

    @Test void noNullsOrBlanks() {
        String[] arr = {"RELIANCE", "TCS", "HDFC"};
        List<String> clean = Arrays.stream(arr)
            .filter(Objects::nonNull)
            .filter(Predicate.not(String::isBlank))
            .toList();
        assertThat(clean).containsExactly("RELIANCE", "TCS", "HDFC");
    }

    @Test void combinedFilter() {
        String[] arr = {"A", null, "", "B"};
        List<String> clean = Arrays.stream(arr)
            .filter(s -> s != null && !s.isBlank())  // combined in one filter
            .toList();
        assertThat(clean).containsExactly("A", "B");
    }
}
